from pathlib import Path
import json,re,hashlib,subprocess
out=Path(__file__).resolve().parent;main=Path('/workspace/orm-main');tree=Path('/workspace/orm-adapted')
load=lambda p:[json.loads(s) for s in p.read_text().splitlines() if s.strip()]
# The old evidence is immutable; this addendum has a separate ledger.
for name,sha in json.loads((out/'evidence-sha256.json').read_text()).items():assert hashlib.sha256((out/name).read_bytes()).hexdigest()==sha,name
for rel,sha in json.loads((out/'adapted-source-hashes.json').read_text()).items():assert hashlib.sha256((tree/rel).read_bytes()).hexdigest()==sha,rel
assert subprocess.check_output(['git','-C',str(main),'rev-parse','HEAD'],text=True).strip()=='219dbb6e7e20ea99d3e5d4b61c0cb14102dc9205'
assert not subprocess.check_output(['git','-C',str(main),'status','--porcelain','--untracked-files=no'])
